import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.D66Xq0Kv.js";const m=JSON.parse('{"title":"LSP Features","description":"","frontmatter":{},"headers":[],"relativePath":"lsp/index.md","filePath":"lsp/index.md"}'),o={name:"lsp/index.md"};function i(r,e,d,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="lsp-features" tabindex="-1">LSP Features <a class="header-anchor" href="#lsp-features" aria-label="Permalink to &quot;LSP Features&quot;">​</a></h1><p>Standard Language Server Protocol features. None of these need configuration except where noted.</p><table tabindex="0"><thead><tr><th>Feature</th><th>What it does</th></tr></thead><tbody><tr><td>Hover</td><td>Kind, type, and documentation of the symbol under the cursor</td></tr><tr><td>Go to definition</td><td>Jumps to the declaration. A class name two packages both declare goes to the one the file imports (an explicit <code>import p::name</code> before a wildcard), then the nearest by path; rename picks the same class</td></tr><tr><td>Find references</td><td>All uses of a symbol, including macros (<code>`WIDTH</code> at its <code>`define</code> or any use). A class method reports its whole override chain, the same set rename edits</td></tr><tr><td>Rename</td><td>Renames a symbol across all references. Keywords cannot be renamed. Refused with a message when the server cannot find the symbol&#39;s declaration (for example a member inherited from a library class that is not in the filelist) or when a module declared more than once in an implicit project would be renamed. A class method renames its whole override chain: the base declaration, every override, <code>extern</code> and out-of-block bodies, <code>super.</code> calls and calls through any handle. The rename is refused, naming the declaration, when that chain reaches a file outside your project (a library such as uvm-core, another project, or a file in no project while yours has one). When a base class is not indexed at all, the rename is refused only if a <code>super.</code> call in the chain shows the method overrides something there; an override that never calls <code>super.</code> is renamed without the base. Limits: <code>implements</code> is not followed, so an interface class method and its implementations rename separately; a same-named non-virtual method in a subclass joins the chain</td></tr><tr><td>Document highlight</td><td>Marks every occurrence of the symbol under the cursor in the current file; for a class method, every occurrence of its override chain</td></tr><tr><td>Selection range</td><td>Expands the selection step by step to each enclosing piece of syntax (smart selection)</td></tr><tr><td>Completion</td><td>Context-aware suggestions; see <a href="./completion">Completion</a></td></tr><tr><td>Signature help</td><td>Parameters while typing a call or a <code>#(...)</code> list; triggers on <code>(</code> and <code>,</code></td></tr><tr><td>Document symbols</td><td>Outline of the current file; see below</td></tr><tr><td>Workspace symbols</td><td>Search across the project; see below</td></tr><tr><td>Inlay hints</td><td>See below</td></tr><tr><td>Folding ranges</td><td>See <a href="./../folding/">Folding</a></td></tr></tbody></table><p>Cross-file features need the project indexed through a filelist. See <a href="./../design/">Design &amp; filelist</a>.</p><h2 id="document-symbols" tabindex="-1">Document symbols <a class="header-anchor" href="#document-symbols" aria-label="Permalink to &quot;Document symbols&quot;">​</a></h2><p>The outline of the current file: modules, interfaces and packages with their ports, parameters, signals, functions, tasks, instances, modports and generate blocks; classes with their properties and methods; typedefs with their enum members and struct fields.</p><h2 id="workspace-symbols" tabindex="-1">Workspace symbols <a class="header-anchor" href="#workspace-symbols" aria-label="Permalink to &quot;Workspace symbols&quot;">​</a></h2><p>A case-insensitive substring search over the open files and the indexed project files (the filelist, or the <a href="./../configuration#without-a-lazyverilog-toml">implicit project</a>):</p><ul><li>modules, interfaces, packages and classes, and each class&#39;s methods, always;</li><li>functions and tasks of packages and modules, and typedefs (struct, enum, other), once the query is not empty.</li></ul><p><code>scope::name</code> matches <code>name</code> inside a package, class or module whose name contains <code>scope</code>, and <code>::scope::name</code> needs the scope to match exactly. An exact name ranks first, then a prefix, then a match at the start of a <code>_</code>-separated word, then anything else; at equal rank, modules, interfaces and packages come before classes, and classes before their members. At most 100 results are returned.</p><h2 id="inlay-hints" tabindex="-1">Inlay hints <a class="header-anchor" href="#inlay-hints" aria-label="Permalink to &quot;Inlay hints&quot;">​</a></h2><p>Inside each module instantiation, LazyVerilog shows the direction and type of every connected port, and an <code>N/M</code> count of connected ports at the opening parenthesis. Instances of modules from the filelist show hints once the background index is ready, so a file opened at startup may briefly show none.</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">[</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">inlay_hint</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">]</span></span>\n<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">enable </span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span></span></code></pre></div><h2 id="folding-ranges" tabindex="-1">Folding ranges <a class="header-anchor" href="#folding-ranges" aria-label="Permalink to &quot;Folding ranges&quot;">​</a></h2><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">[</span><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">folding</span><span style="--shiki-light:#7C7F93;--shiki-dark:#9399B2;">]</span></span>\n<span class="line"><span style="--shiki-light:#4C4F69;--shiki-dark:#CDD6F4;">enable </span><span style="--shiki-light:#179299;--shiki-dark:#94E2D5;">=</span><span style="--shiki-light:#FE640B;--shiki-dark:#FAB387;"> true</span></span></code></pre></div><p>Neovim asks for folds and inlay hints on every edit. With <code>enable = false</code> the server answers with nothing. To stop the requests altogether, also set <code>folding = false</code> or <code>inlay_hints = false</code> in the Neovim <a href="./../installation/neovim"><code>setup()</code></a>.</p>',16)])])}const u=t(o,[["render",i]]);export{m as __pageData,u as default};
